-- A sheet's parent sheet, not dated: a grade with no rate in force on a date on the sheet takes the
-- parent's (then the parent's parent's, up to three levels up). Null is none.
ALTER TABLE sheet ADD COLUMN parent_id VARCHAR(200);

    /** The sheet's rates by grade, each grade's from the earliest; a grade with no rate is not listed.
     *  As they stand now, or as they stood at the end of the screen's as-of date. */
    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOf) {
        return service.list(sheetId.trim(), AsOf.parse(asOf)).stream().map(this::view).toList();
    }

    /** The rates of the sheets the sheet's rates fall back to, nearest first (its parent, the
     *  parent's parent, up to three levels up), each listed as {@link #list} lists them as they stand
     *  now; under the screen's as-of date, the parents the sheet had at the end of that day. */
    @GetMapping("/inherited")
    public List<List<RateView>> inherited(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOf) {
        LocalDate day = AsOf.parse(asOf);
        return service.ancestors(sheetId.trim(), day).stream()
                .map(ancestor -> service.list(ancestor).stream().map(this::view).toList())
                .toList();
    }

    /** Set the rate for a grade (A, B or C) from a date, replacing the one it had from that date. */
    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated RateRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return view(rollups.track(sheet, by, () -> service.set(sheet, by, grade, request.from(),
                request.to(), request.rate())));
    }

    /** Set a rate per pasted line, in order, each as the form would; none when any line is refused.
     *  The rates set, in the order of their lines. */
    @PostMapping("/import")
    public List<RateView> importRates(@PathVariable @NotBlank @Size(max = 200) String sheetId,
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's rates by grade, each grade's from the earliest. */
  readonly rates = signal<Rate[]>([]);
  /** The rates of the sheets the sheet's rates fall back to, nearest first, each listed as `rates`. */
  readonly inherited = signal<Rate[][]>([]);
  /** Each grade's rates by grade; a grade with no rate is absent. */
  readonly byGrade = computed(() => byGradeOf(this.rates()));
  /** Each fall-back sheet's rates by grade, nearest first. */
  private readonly inheritedByGrade = computed(() => this.inherited().map(byGradeOf));
  /** Each grade's rate in force on the sheet's today, falling back to the parent sheets'; a grade
   *  with none is absent. */
  readonly current = computed(() => {
    const today = this.session.today();
    const map = new Map<string, string>();
    if (!today) return map;
    for (const grade of GRADES) {
      const rate = rateOn(this.ofOn(grade, today), today);
      if (rate !== null) map.set(grade, rate);
    }
    return map;
  });
  /** The months (yyyy-mm) of the calendar year of the sheet's today; none when it has no today. */
  readonly months = computed(() => {
    const year = this.session.today()?.slice(0, 4);
    if (!year) return [];
    return Array.from({ length: 12 }, (_, i) => `${year}-${String(i + 1).padStart(2, '0')}`);
  });
  /** For each grade and month of `months`, the rate in force on the month's first day, falling back
   *  to the parent sheets' as `current` does; null when none is. Keyed grade-yyyy-mm. */
  readonly calendar = computed(() => {
    const map = new Map<string, string | null>();
    for (const grade of GRADES) {
      for (const month of this.months()) {
        const first = `${month}-01`;
        map.set(`${grade}-${month}`, rateOn(this.ofOn(grade, first), first));
      }
    }
    return map;
  });

  /** A grade's rates; none when the grade has no rate. */
  of(grade: string): Rate[] {
    return this.byGrade().get(grade) ?? [];
  }

  /** A grade's rates to work a date's rate from: the sheet's own when one is in force on the date,
   *  else those of the nearest parent sheet with one in force on it; the sheet's own when none is.
   *  For a claim (its id), only the rates as they apply to it count (see ratesFor). */
  ofOn(grade: string, date: string, claimId?: number): Rate[] {
    const of = (rates: Rate[]) => (claimId === undefined ? rates : ratesFor(rates, claimId));
    const own = of(this.of(grade));
    if (rateOn(own, date) !== null) return own;
    for (const level of this.inheritedByGrade()) {
      const theirs = of(level.get(grade) ?? []);
      if (rateOn(theirs, date) !== null) return theirs;
    }
    return own;
  }

  /** The rates of a person's grade in force on a claim's date to work the claim's rate from, as they
   *  apply to the claim (see ofOn); none when that grade has no rate. */
  ofGradeOn(grades: PersonGrade[], claim: { id: number; date: string }): Rate[] {
    const grade = gradeOn(grades, claim.date);
    return grade === null ? [] : this.ofOn(grade, claim.date, claim.id);
  }

  constructor() {
    effect(() => {
      const sheet = this.session.sheetId();
      const load = this.session.loads();
      this.rates.set([]);
      this.inherited.set([]);
      if (sheet) void this.read(sheet, load);
    });
  }

  /** Re-read the rates the active sheet falls back to: its parent sheet has changed. */
  async readInherited(): Promise<void> {
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const load = this.session.loads();
    const inherited = await firstValueFrom(
      this.http.get<Rate[][]>(`/api/sheets/${encodeURIComponent(sheet)}/rates/inherited`),
    );
    if (this.session.loads() !== load || this.session.sheetId() !== sheet) return;
    this.inherited.set(inherited);
  }

  /** Set a grade's rate from a date (null: from the beginning of time) through a date (null: no
   *  end) on the active sheet, replacing the one the grade had from that date. */
  async set(grade: string, rate: string, from: string | null, to: string | null): Promise<void> {
    const sheet = this.session.sheetId();
    if (!sheet) throw new Error('No sheet loaded.');
    const saved = await firstValueFrom(
      this.http.put<Rate>(`/api/sheets/${encodeURIComponent(sheet)}/rates/${grade}`, { rate, from, to }),
    );
    if (this.session.sheetId() !== sheet) return;
    this.rates.update((list) =>
      [...list.filter((r) => r.grade !== saved.grade || r.from !== saved.from), saved].sort(byGradeAndFrom),
            }
            found.addAll(children);
            next = children;
        }
        return found;
    }

    /** The ids of the other sheets of the sheet's tree: its ancestors (its parent, the parent's parent,
     *  and so on) and its descendants, among the sheets that exist; the sheet itself is not among them. */
    public List<String> tree(String id) {
        List<String> found = new ArrayList<>();
        Set<String> seen = new HashSet<>(Set.of(id));
        for (String up = sheets.findById(id).map(Sheet::getParentId).orElse(null); up != null && seen.add(up);
                up = sheets.findById(up).map(Sheet::getParentId).orElse(null)) {
            if (sheets.existsById(up)) {
                found.add(up);
            }
        }
        for (String down : descendants(id)) {
            if (!found.contains(down)) {
                found.add(down);
            }
        }
        return found;
    }

    /** Whether a sheet with this id was ever used (loaded or changed). */
    public boolean exists(String id) {
        return sheets.existsById(id);
    }

    /** Whether the sheet is archived: every change to it is then refused. */
    public boolean isArchived(String id) {
        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
    }

    /** Archive the sheet; refused when it is archived already. */
    @Transactional
    public Sheet archive(String id, String by) {
        load(id);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        if (sheet.isArchived()) {
            throw new ArchiveRefusedException("the sheet is archived already");
        }
        sheet.archive();
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + by);
        return saved;
    }
}

